/*  ---- #260 NAME: Oontheeswarar -> Oondreswarar ------------------   */
/*  Owner ruling. THREE things had to change, not one:                 */
/*    (1) TEMPLES[260].name      'Oontheeswarar' -> 'Oondreswarar'     */
/*    (2) TEMPLES[260].name_ta   'ஊந்தீஸ்வரர்' -> 'ஊன்றீஸ்வரர்'                  */
/*        The Tamil in NAME_TA_MORE was a transliteration of the       */
/*        WRONG English and was itself wrong. The correct form is      */
/*        ஊன்றீஸ்வரர், from ஊன்றுகோல் (oondru-kol), the walking STICK      */
/*        given to the blinded Sundarar. This is why the fix had to    */
/*        be made "in both Tamil and English".                         */
/*    (3) the Wikipedia search URLs, which applyDataPatches() builds   */
/*        from t.name and would otherwise still query the old form.    */
/*  NOTE ON MECHANISM: NAME_TA_MORE is a const inside the first IIFE   */
/*  and is not reachable from here, so name_ta is written directly on  */
/*  the temple record. applyDataPatches() only assigns name_ta when it */
/*  is falsy, so this value survives regardless of load order.         */
/*  The 2B.33 prose spelling 'Oondreeswarar' has also been harmonised  */
/*  to 'Oondreswarar' throughout that block.                           */
/*                                                                     */
/*  ---- #245 THIRUKKACHUR: NO COORDINATE SUPPLIED ------------------  */
/*  #245 was listed by name in the owner's coordinate set but no       */
/*  lat/lng followed it. Nothing has been changed for #245. Its        */
/*  current value (12.77611, 79.99722) came from Session 1D.4, not     */
/*  from owner GPS. Because Thirukkachur is a TWIN shrine - the        */
/*  Kachabeswarar temple at the foot and the Marundeeswarar temple     */
/*  about a kilometre away on Oushadhamalai - a single pin is          */
/*  ambiguous here by nature, and owner GPS is specifically requested. */
/*                                                                     */
/*  ---- TWO LARGER MOVES, BOTH ACCEPTED ---------------------------   */
/*  #238 Thirumetrali moves 1519 m. Its previous value was base data,  */
/*  never verified; the new value sits in the Kanchipuram temple       */
/*  cluster a few hundred metres from #240, which is consistent.       */
/*  #255 Cheyyar moves 835 m due south on the same longitude. In       */
/*  2B.33 this record was marked coords_verified against a published   */
/*  town centroid; owner GPS supersedes that and the earlier           */
/*  "agrees within ~150 m" note is withdrawn.                          */
/*                                                                     */
/*  ---- #257 KOOVAM: FLAG FROM 2B.33 RESOLVED ---------------------   */
/*  2B.33 left #257 unverified because the base record and the         */
/*  Wikipedia TOWN centroid (13.0122, 79.8149) disagreed by ~1.7 km.   */
/*  Owner GPS lands 60 m from the BASE value, so the base record was   */
/*  right and the town centroid was the outlier. Now verified.         */
/* ================================================================== */
(function() {
  'use strict';
  if (window.SESSION_2B34FIX_LOADED) return;
  window.SESSION_2B34FIX_LOADED = true;

  if (!window.TEMPLES || !Array.isArray(window.TEMPLES)) {
    console.warn('[Session 2B.34FIX] window.TEMPLES not available - fix skipped.');
    return;
  }
  var find = function(sno){ return window.TEMPLES.find(function(x){ return x.sno === sno; }); };

  // ---------- 1. #260 NAME FIX (English + Tamil + wiki URLs) ----------
  (function fixName260(){
    var t = find(260);
    if (!t) return;
    var oldName = t.name, oldTa = t.name_ta;
    t.name    = 'Oondreswarar';
    t.name_ta = 'ஊன்றீஸ்வரர்';
    var q = 'https://en.wikipedia.org/wiki/Special:Search?search=' +
            encodeURIComponent(t.name + ' Temple ' + t.town) + '&go=Go';
    t.wiki = q; t.wiki_en = q; t.wiki_ta = q;
    console.log('[Session 2B.34FIX] #260 name: "' + oldName + '" -> "' + t.name + '"');
    console.log('[Session 2B.34FIX] #260 name_ta: "' + oldTa + '" -> "' + t.name_ta +
                '" (the old Tamil transliterated the incorrect English)');
  })();

  // ---------- 2. OWNER GPS COORDINATES (17 temples) ----------
  var gps = [
    { sno: 238, lat: 12.835146270003108, lng: 79.69137984906834 },
    { sno: 239, lat: 12.850464511136899, lng: 79.69436431478390 },
    { sno: 240, lat: 12.840794327918037, lng: 79.69130200316627 },
    { sno: 241, lat: 12.829212997140473, lng: 79.71750644350259 },
    { sno: 242, lat: 12.718532577012803, lng: 79.75526454885934 },
    { sno: 243, lat: 13.003718152101326, lng: 79.80929584793161 },
    { sno: 244, lat: 13.071547369128915, lng: 80.11481856696197 },
    { sno: 246, lat: 12.698362678552243, lng: 80.03040349143531 },
    { sno: 248, lat: 12.400999286959273, lng: 79.81773856050452 },
    { sno: 251, lat: 13.136493890059715, lng: 80.13229718347851 },
    { sno: 254, lat: 12.767283090260939, lng: 79.69075774070589 },
    { sno: 255, lat: 12.648878755152055, lng: 79.54052895511130 },
    { sno: 256, lat: 12.800921171304390, lng: 79.61343590792053 },
    { sno: 257, lat: 13.021238570974768, lng: 79.82687321790166 },
    { sno: 259, lat: 13.140712876758537, lng: 79.87638067178345 },
    { sno: 260, lat: 13.207976957830484, lng: 79.87879423826975 },
    { sno: 261, lat: 13.245230926862229, lng: 80.09528280263042 }
  ];

  function metres(a, b, c, d) {
    var R = 6371000, r = Math.PI / 180;
    var x = Math.pow(Math.sin((c - a) * r / 2), 2) +
            Math.cos(a * r) * Math.cos(c * r) * Math.pow(Math.sin((d - b) * r / 2), 2);
    return 2 * R * Math.asin(Math.sqrt(x));
  }

  var applied = 0, moved = [];
  gps.forEach(function(f) {
    var t = find(f.sno);
    if (!t) { console.warn('[Session 2B.34FIX] sno ' + f.sno + ' not found'); return; }
    var oL = t.lat, oG = t.lng, d = metres(oL, oG, f.lat, f.lng);
    t.lat = f.lat; t.lng = f.lng;
    t.coords_verified = true;
    t.coords_source = 'Owner GPS, Session 2B.34FIX. Confidence: HIGH (on-the-ground reading).';
    applied++;
    if (d > 400) moved.push(f.sno + ' (' + Math.round(d) + ' m)');
    console.log('[Session 2B.34FIX] Coord sno ' + f.sno + ': (' + oL + ', ' + oG +
                ') -> (' + f.lat + ', ' + f.lng + ')  [' + d.toFixed(1) + ' m]');
  });

  // Mirror onto the enrichment records so the detail panel agrees with the map.
  if (window.TEMPLE_ENRICHMENT) {
    gps.forEach(function(f) {
      var e = window.TEMPLE_ENRICHMENT[f.sno];
      if (e) e.coords_verified = true;
    });
  }

  console.log('[Session 2B.34FIX] Applied ' + applied + ' owner-GPS coordinates across #238-#261.');
  console.log('[Session 2B.34FIX] 15 of 17 were sub-60 m refinements. Larger moves accepted: ' +
              (moved.join(', ') || 'none') +
              ' - #238 was never-verified base data and now sits in the Kanchipuram cluster beside #240; ' +
              '#255 moves due south on the same longitude and supersedes the town-centroid value used in 2B.33.');
  console.log('[Session 2B.34FIX] #257 Koovam: the 2B.33 UNVERIFIED flag is now RESOLVED. Owner GPS falls 60 m from the BASE record, confirming the base value was correct and the Wikipedia town centroid (13.0122, 79.8149) was the outlier.');
  console.log('[Session 2B.34FIX] #245 Thirukkachur: NO COORDINATE SUPPLIED - listed by name only, so nothing was changed. Its current value came from Session 1D.4, not owner GPS. Note that Thirukkachur is a TWIN shrine (Kachabeswarar at the foot, Marundeeswarar ~1 km away on Oushadhamalai), so one pin is inherently ambiguous. OWNER GPS REQUESTED.');
  console.log('[Session 2B.34FIX] #260: name and Tamil name corrected, and the Wikipedia search URLs rebuilt from the new name.');

  setTimeout(function(){ try { if (window.state && typeof window.render === 'function') window.render(); } catch(e){} }, 1500);
})();

